  "v_msad_u8": ["Calculate the sum of absolute differences of elements in two packed 4-component unsigned 8-bit integer inputs, except that elements where the second input (known as the reference input) is zero are not included in the sum. Add an unsigned 32-bit integer value from the third input and store the result into a vector register.","VALU",[],[],[["VOP3",484,64,"default",[["vdst","W","VGPR","U32",32,false],["src0","R","SRC_NOLIT","B32",32,false],["src1","R","SRC_SIMPLE","B32",32,false],["src2","R","SRC_SIMPLE","B32",32,false]]]]],
