  "v_pk_max_i16": ["Select the component-wise maximum of two packed signed 16-bit integer inputs and store the selected values into a vector register.","VALU",[],[],[["VOP3P",7,64,"default",[["vdst","W","VGPR","PK2_I16",32,false],["src0","R","SRC_NOLIT","PK2_I16",32,false],["src1","R","SRC_SIMPLE","PK2_I16",32,false]]]]],
