  "v_pk_min_i16": ["Select the component-wise minimum of two packed signed 16-bit integer inputs and store the selected values into a vector register.","VALU",[],[],[["VOP3P",8,64,"default",[["vdst","W","VGPR","PK2_I16",32,false],["src0","R","SRC_NOLIT","PK2_I16",32,false],["src1","R","SRC_SIMPLE","PK2_I16",32,false]]]]],
