  "v_pk_mov_b32": ["Move data from two vector inputs into two vector registers.","VALU",[],[],[["VOP3P",51,64,"default",[["vdst","W","VGPR","PK2_B32",64,false],["src0","R","SRC_NOLIT","PK2_B32",64,false],["src1","R","SRC_SIMPLE","PK2_B32",64,false]]]]],
  "v_pk_mul_f16": ["Multiply two packed half-precision float inputs component-wise and store the result into a vector register.","VALU",[],[],[["VOP3P",16,64,"default",[["vdst","W","VGPR","PK2_F16",32,false],["src0","R","SRC_NOLIT","PK2_F16",32,false],["src1","R","SRC_SIMPLE","PK2_F16",32,false]]]]],
