  "v_prng_b32": ["Generate a pseudorandom number using an LFSR (linear feedback shift register) seeded with the vector input, then store the result into a vector register.","VALU",[],[],[["VOP1",88,32,"default",[["vdst","W","VGPR","B32",32,false],["src0","R","SRC","B32",32,false]]],["VOP1_INST_LITERAL",88,64,"has_lit",[["vdst","W","VGPR","B32",32,false],["literal","R","SRC","B32",32,false]]],["VOP1_VOP_DPP",88,64,"has_dpp",[["vdst","W","VGPR","B32",32,false],["vsrc0","R","VGPR","B32",32,false]]],["VOP1_VOP_SDWA",88,64,"has_sdwa",[["vdst","W","VGPR","B32",32,false],["vsrc0","R","SRC_SIMPLE","B32",32,false]]],["VOP3",408,64,"default",[["vdst","W","VGPR","B32",32,false],["src0","R","SRC_NOLIT","B32",32,false]]]]],
  "v_qsad_pk_u16_u8": ["Perform the V_SAD_U8 operation four times using different slices of the first array, all entries of the second array and each entry of the third array. Truncate each result to 16 bits, pack the values into a 4-entry array and store the array into a vector register. The first input is an 8-entry array of unsigned 8-bit integers, the second input is a 4-entry array of unsigned 8-bit integers and the third input is a 4-entry array of unsigned 16-bit integers.","VALU",[],[],[["VOP3",485,64,"default",[["vdst","W","VGPR","B64",64,false],["src0","R","SRC_NOLIT","B64",64,false],["src1","R","SRC_SIMPLE","B32",32,false],["src2","R","SRC_SIMPLE","B64",64,false]]]]],
  "v_rcp_f16": ["Calculate the reciprocal of the half-precision float input using IEEE rules and store the result into a vector register.","VALU",["TRANSCENDENTAL"],[],[["VOP1",61,32,"default",[["vdst","W","VGPR","F16",16,false],["src0","R","SRC","F16",16,false]]],["VOP1_INST_LITERAL",61,64,"has_lit",[["vdst","W","VGPR","F16",16,false],["literal","R","SRC","F16",16,false]]],["VOP1_VOP_DPP",61,64,"has_dpp",[["vdst","W","VGPR","F16",16,false],["vsrc0","R","VGPR","F16",16,false]]],["VOP1_VOP_SDWA",61,64,"has_sdwa",[["vdst","W","VGPR","F16",16,false],["vsrc0","R","SRC_SIMPLE","F16",16,false]]],["VOP3",381,64,"default",[["vdst","W","VGPR","F16",16,false],["src0","R","SRC_NOLIT","F16",16,false]]]]],
