  "v_rcp_iflag_f32": ["Calculate the reciprocal of the vector float input in a manner suitable for integer division and store the result into a vector register. This opcode is intended for use as part of an integer division macro.","VALU",["TRANSCENDENTAL"],[],[["VOP1",35,32,"default",[["vdst","W","VGPR","F32",32,false],["src0","R","SRC","F32",32,false]]],["VOP1_INST_LITERAL",35,64,"has_lit",[["vdst","W","VGPR","F32",32,false],["literal","R","SRC","F32",32,false]]],["VOP1_VOP_DPP",35,64,"has_dpp",[["vdst","W","VGPR","F32",32,false],["vsrc0","R","VGPR","F32",32,false]]],["VOP1_VOP_SDWA",35,64,"has_sdwa",[["vdst","W","VGPR","F32",32,false],["vsrc0","R","SRC_SIMPLE","F32",32,false]]],["VOP3",355,64,"default",[["vdst","W","VGPR","F32",32,false],["src0","R","SRC_NOLIT","F32",32,false]]]]],
  "v_readfirstlane_b32": ["Read the scalar value in the lowest active lane of the input vector register and store it into a scalar register.","VALU",[],[],[["VOP1",2,32,"default",[["vdst","W","SREG_NOVCC","B32",32,false],["src0","R","VGPR_OR_LDS","B32",32,false]]],["VOP3",322,64,"default",[["vdst","W","SREG_NOVCC","B32",32,false],["src0","R","VGPR_OR_LDS","B32",32,false]]]]],
  "v_readlane_b32": ["Read the scalar value in the specified lane of the first input where the lane select is in the second input. Store the result into a scalar register.","VALU",[],[],[["VOP3",649,64,"default",[["vdst","W","SREG_NOVCC","B32",32,false],["src0","R","VGPR_OR_LDS","B32",32,false],["src1","R","SSRC_LANESEL","B32",32,false]]]]],
