  "v_rndne_f64": ["Round the double-precision float input to the nearest even integer and store the result in floating point format into a vector register.","VALU",[],[],[["VOP1",25,32,"default",[["vdst","W","VGPR","F64",64,false],["src0","R","SRC","F64",64,false]]],["VOP1_INST_LITERAL",25,64,"has_lit",[["vdst","W","VGPR","F64",64,false],["literal","R","SRC","F64",64,false]]],["VOP3",345,64,"default",[["vdst","W","VGPR","F64",64,false],["src0","R","SRC_NOLIT","F64",64,false]]]]],
  "v_rsq_f16": ["Calculate the reciprocal of the square root of the half-precision float input using IEEE rules and store the result into a vector register.","VALU",["TRANSCENDENTAL"],[],[["VOP1",63,32,"default",[["vdst","W","VGPR","F16",16,false],["src0","R","SRC","F16",16,false]]],["VOP1_INST_LITERAL",63,64,"has_lit",[["vdst","W","VGPR","F16",16,false],["literal","R","SRC","F16",16,false]]],["VOP1_VOP_DPP",63,64,"has_dpp",[["vdst","W","VGPR","F16",16,false],["vsrc0","R","VGPR","F16",16,false]]],["VOP1_VOP_SDWA",63,64,"has_sdwa",[["vdst","W","VGPR","F16",16,false],["vsrc0","R","SRC_SIMPLE","F16",16,false]]],["VOP3",383,64,"default",[["vdst","W","VGPR","F16",16,false],["src0","R","SRC_NOLIT","F16",16,false]]]]],
  "v_rsq_f32": ["Calculate the reciprocal of the square root of the single-precision float input using IEEE rules and store the result into a vector register.","VALU",["TRANSCENDENTAL"],[],[["VOP1",36,32,"default",[["vdst","W","VGPR","F32",32,false],["src0","R","SRC","F32",32,false]]],["VOP1_INST_LITERAL",36,64,"has_lit",[["vdst","W","VGPR","F32",32,false],["literal","R","SRC","F32",32,false]]],["VOP1_VOP_DPP",36,64,"has_dpp",[["vdst","W","VGPR","F32",32,false],["vsrc0","R","VGPR","F32",32,false]]],["VOP1_VOP_SDWA",36,64,"has_sdwa",[["vdst","W","VGPR","F32",32,false],["vsrc0","R","SRC_SIMPLE","F32",32,false]]],["VOP3",356,64,"default",[["vdst","W","VGPR","F32",32,false],["src0","R","SRC_NOLIT","F32",32,false]]]]],
