  "v_sad_hi_u8": ["Calculate the sum of absolute differences of elements in two packed 4-component unsigned 8-bit integer inputs, shift the sum left by 16 bits, add an unsigned 32-bit integer value from the third input and store the result into a vector register.","VALU",[],[],[["VOP3",474,64,"default",[["vdst","W","VGPR","U32",32,false],["src0","R","SRC_NOLIT","PK4_U8",32,false],["src1","R","SRC_SIMPLE","PK4_U8",32,false],["src2","R","SRC_SIMPLE","U32",32,false]]]]],
  "v_sad_u16": ["Calculate the sum of absolute differences of elements in two packed 2-component unsigned 16-bit integer inputs, add an unsigned 32-bit integer value from the third input and store the result into a vector register.","VALU",[],[],[["VOP3",475,64,"default",[["vdst","W","VGPR","U32",32,false],["src0","R","SRC_NOLIT","PK2_U16",32,false],["src1","R","SRC_SIMPLE","PK2_U16",32,false],["src2","R","SRC_SIMPLE","U32",32,false]]]]],
  "v_sad_u32": ["Calculate the absolute difference of two unsigned 32-bit integer inputs, add an unsigned 32-bit integer value from the third input and store the result into a vector register.","VALU",[],[],[["VOP3",476,64,"default",[["vdst","W","VGPR","U32",32,false],["src0","R","SRC_NOLIT","U32",32,false],["src1","R","SRC_SIMPLE","U32",32,false],["src2","R","SRC_SIMPLE","U32",32,false]]]]],
  "v_sad_u8": ["Calculate the sum of absolute differences of elements in two packed 4-component unsigned 8-bit integer inputs, add an unsigned 32-bit integer value from the third input and store the result into a vector register.","VALU",[],[],[["VOP3",473,64,"default",[["vdst","W","VGPR","U32",32,false],["src0","R","SRC_NOLIT","PK4_U8",32,false],["src1","R","SRC_SIMPLE","PK4_U8",32,false],["src2","R","SRC_SIMPLE","U32",32,false]]]]],
  "v_sat_pk_u8_i16": ["Given 2 signed 16-bit integer inputs, saturate each input over an unsigned 8-bit integer range, pack the resulting values into a packed 16-bit value and store the result into a vector register.","VALU",[],[],[["VOP1",79,32,"default",[["vdst","W","VGPR","PK2_U8",16,false],["src0","R","SRC","PK2_I16",32,false]]],["VOP1_INST_LITERAL",79,64,"has_lit",[["vdst","W","VGPR","PK2_U8",16,false],["literal","R","SRC","PK2_I16",32,false]]],["VOP1_VOP_DPP",79,64,"has_dpp",[["vdst","W","VGPR","PK2_U8",16,false],["vsrc0","R","VGPR","PK2_I16",32,false]]],["VOP1_VOP_SDWA",79,64,"has_sdwa",[["vdst","W","VGPR","PK2_U8",16,false],["vsrc0","R","SRC_SIMPLE","PK2_I16",32,false]]],["VOP3",399,64,"default",[["vdst","W","VGPR","PK2_U8",16,false],["src0","R","SRC_NOLIT","PK2_I16",32,false]]]]],
  "v_screen_partition_4se_b32": ["4SE version of LUT instruction for screen partitioning/filtering. This opcode is intended to help accelerate screen partitioning in the 4SE case only. 2SE and 1SE cases use normal ALU instructions.","VALU",[],[],[["VOP1",55,32,"default",[["vdst","W","VGPR","B32",32,false],["src0","R","SRC","B32",32,false]]],["VOP1_INST_LITERAL",55,64,"has_lit",[["vdst","W","VGPR","B32",32,false],["literal","R","SRC","B32",32,false]]],["VOP1_VOP_DPP",55,64,"has_dpp",[["vdst","W","VGPR","B32",32,false],["vsrc0","R","VGPR","B32",32,false]]],["VOP1_VOP_SDWA",55,64,"has_sdwa",[["vdst","W","VGPR","B32",32,false],["vsrc0","R","SRC_SIMPLE","B32",32,false]]],["VOP3",375,64,"default",[["vdst","W","VGPR","B32",32,false],["src0","R","SRC_NOLIT","B32",32,false]]]]],
  "v_sin_f16": ["Calculate the trigonometric sine of a half-precision float value using IEEE rules and store the result into a vector register. The operand is calculated by scaling the vector input by 2 PI.","VALU",["TRANSCENDENTAL"],[],[["VOP1",73,32,"default",[["vdst","W","VGPR","F16",16,false],["src0","R","SRC","F16",16,false]]],["VOP1_INST_LITERAL",73,64,"has_lit",[["vdst","W","VGPR","F16",16,false],["literal","R","SRC","F16",16,false]]],["VOP1_VOP_DPP",73,64,"has_dpp",[["vdst","W","VGPR","F16",16,false],["vsrc0","R","VGPR","F16",16,false]]],["VOP1_VOP_SDWA",73,64,"has_sdwa",[["vdst","W","VGPR","F16",16,false],["vsrc0","R","SRC_SIMPLE","F16",16,false]]],["VOP3",393,64,"default",[["vdst","W","VGPR","F16",16,false],["src0","R","SRC_NOLIT","F16",16,false]]]]],
  "v_sin_f32": ["Calculate the trigonometric sine of a single-precision float value using IEEE rules and store the result into a vector register. The operand is calculated by scaling the vector input by 2 PI.","VALU",["TRANSCENDENTAL"],[],[["VOP1",41,32,"default",[["vdst","W","VGPR","F32",32,false],["src0","R","SRC","F32",32,false]]],["VOP1_INST_LITERAL",41,64,"has_lit",[["vdst","W","VGPR","F32",32,false],["literal","R","SRC","F32",32,false]]],["VOP1_VOP_DPP",41,64,"has_dpp",[["vdst","W","VGPR","F32",32,false],["vsrc0","R","VGPR","F32",32,false]]],["VOP1_VOP_SDWA",41,64,"has_sdwa",[["vdst","W","VGPR","F32",32,false],["vsrc0","R","SRC_SIMPLE","F32",32,false]]],["VOP3",361,64,"default",[["vdst","W","VGPR","F32",32,false],["src0","R","SRC_NOLIT","F32",32,false]]]]],
